CompositionLocalProvider(LocalConfiguration provides locale) {
    MonarchFunnelChart(
        title = {{title}},
        stages = listOf(
            MonarchFunnelChartStage({{stages.0.label}}, {{stages.0.value|double}}, key = {{stages.0.key}}),
            MonarchFunnelChartStage({{stages.1.label}}, {{stages.1.value|double}}, key = {{stages.1.key}}),
            MonarchFunnelChartStage({{stages.2.label}}, {{stages.2.value|double}}, key = {{stages.2.key}}),
            MonarchFunnelChartStage({{stages.3.label}}, {{stages.3.value|double}}, key = {{stages.3.key}}),
            MonarchFunnelChartStage({{stages.4.label}}, {{stages.4.value|double}}, key = {{stages.4.key}}),
        ),
        description = {{description}},
    )
}

examples.setupTemplate:
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag({{locale}})) }
}

